	defer srv.Close()

	cli := New(srv.URL, WithHTTPClient(srv.Client()))
	_, err := cli.Download(context.Background(), testModule())
	if err == nil {
		t.Fatal("expected error for missing X-Terraform-Get header")
	}
}

